CREATE TABLE IF NOT EXISTS "user" (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, "emailVerified" boolean NOT NULL DEFAULT false, image text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), "twoFactorEnabled" boolean DEFAULT false);
CREATE TABLE IF NOT EXISTS session (id text PRIMARY KEY, "expiresAt" timestamptz NOT NULL, token text NOT NULL UNIQUE, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), "ipAddress" text, "userAgent" text, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS account (id text PRIMARY KEY, "accountId" text NOT NULL, "providerId" text NOT NULL, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, scope text, password text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, "expiresAt" timestamptz NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "twoFactor" (id text PRIMARY KEY, secret text NOT NULL, "backupCodes" text NOT NULL, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, verified boolean DEFAULT true);
CREATE INDEX ON session ("userId");
CREATE INDEX ON verification (identifier);
CREATE TABLE installation (id integer PRIMARY KEY CHECK (id=1), owner_id text REFERENCES "user"(id), completed_at timestamptz);
INSERT INTO installation(id) VALUES(1);
CREATE TABLE staff_profile (user_id text PRIMARY KEY REFERENCES "user"(id), role text NOT NULL CHECK(role IN ('owner','manager','dispatch','sales','finance','crew','client')), active boolean NOT NULL DEFAULT true);
CREATE TABLE client (id uuid PRIMARY KEY, name text NOT NULL, email text, phone text, billing_address text, quickbooks_id text UNIQUE, archived boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE contact (id uuid PRIMARY KEY, client_id uuid NOT NULL REFERENCES client(id), name text NOT NULL, email text, phone text, kind text NOT NULL DEFAULT 'site');
CREATE TABLE property (id uuid PRIMARY KEY, client_id uuid NOT NULL REFERENCES client(id), name text NOT NULL, address text NOT NULL, acreage numeric CHECK(acreage>=0), access_instructions text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', archived boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON property(client_id);
CREATE TABLE client_access (user_id text NOT NULL REFERENCES "user"(id), client_id uuid NOT NULL REFERENCES client(id), PRIMARY KEY(user_id,client_id));
CREATE TABLE invitation (id uuid PRIMARY KEY, email text NOT NULL, role text NOT NULL CHECK(role IN ('manager','dispatch','sales','finance','crew','client')), client_id uuid REFERENCES client(id), token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, accepted_at timestamptz, CHECK(role<>'client' OR client_id IS NOT NULL));
CREATE TABLE work_order (id uuid PRIMARY KEY, property_id uuid NOT NULL REFERENCES property(id), title text NOT NULL, scope text NOT NULL DEFAULT '', assigned_to text REFERENCES "user"(id), scheduled_at timestamptz, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','scheduled','in_progress','completed','reviewed','cancelled','skipped','delayed')), version integer NOT NULL DEFAULT 1, checklist jsonb NOT NULL DEFAULT '[]', prerequisites jsonb NOT NULL DEFAULT '[]', override_reason text, published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON work_order(assigned_to,scheduled_at);
CREATE TABLE field_event (id uuid PRIMARY KEY, work_order_id uuid NOT NULL REFERENCES work_order(id), user_id text NOT NULL REFERENCES "user"(id), kind text NOT NULL CHECK(kind IN ('note','issue','time','checklist','complete')), payload jsonb NOT NULL, base_version integer NOT NULL, conflict boolean NOT NULL DEFAULT false, published boolean NOT NULL DEFAULT false, captured_at timestamptz NOT NULL, received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE lead (id uuid PRIMARY KEY, name text NOT NULL, email text NOT NULL, phone text, location text NOT NULL, description text NOT NULL, source text, status text NOT NULL DEFAULT 'new', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE estimate (id uuid PRIMARY KEY, property_id uuid NOT NULL REFERENCES property(id), title text NOT NULL, revision integer NOT NULL DEFAULT 1, amount_cents bigint NOT NULL CHECK(amount_cents>=0), scope text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','sent','approved','declined')), approved_by text REFERENCES "user"(id), approved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE billing_draft (id uuid PRIMARY KEY, property_id uuid NOT NULL REFERENCES property(id), estimate_id uuid REFERENCES estimate(id), title text NOT NULL, amount_cents bigint NOT NULL CHECK(amount_cents>0), kind text NOT NULL CHECK(kind IN ('service','deposit','progress','final')), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved','posted','failed')), quickbooks_id text UNIQUE, balance_cents bigint, payment_url text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE service_request (id uuid PRIMARY KEY, property_id uuid NOT NULL REFERENCES property(id), user_id text NOT NULL REFERENCES "user"(id), description text NOT NULL, status text NOT NULL DEFAULT 'new', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assessment_slot (id uuid PRIMARY KEY, starts_at timestamptz NOT NULL UNIQUE, ends_at timestamptz NOT NULL, property_id uuid REFERENCES property(id), booked_by text REFERENCES "user"(id), CHECK(ends_at>starts_at));
CREATE TABLE audit_event (id uuid PRIMARY KEY, user_id text REFERENCES "user"(id), action text NOT NULL, entity_id text, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox (id uuid PRIMARY KEY, kind text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), locked_at timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON outbox(status,available_at);
CREATE TABLE file_record (id uuid PRIMARY KEY, property_id uuid NOT NULL REFERENCES property(id), work_order_id uuid REFERENCES work_order(id), user_id text NOT NULL REFERENCES "user"(id), object_key text NOT NULL UNIQUE, name text NOT NULL, mime text NOT NULL, bytes integer NOT NULL CHECK(bytes>0), status text NOT NULL DEFAULT 'pending', published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
